import React, { useState, useEffect, useRef, useCallback } from 'react';
import { verifyOtpForTpin, generateOtpForResendTpin } from "../../../api/login/Login";
import { Modal } from 'react-bootstrap';
import { toast } from 'react-toastify';
import './Dashboard.css';

const DashboardOtpModal = ({ 
  modalVisibility, 
  handleCloseModal3, 
  handleSubmitmodal3, 
  storedUserid,
  setModalVisibility,
  getUserTpinStatus
}) => {
  const length = 6;
  const [otp, setOtp] = useState(new Array(length).fill(''));
  const [timeLeft, setTimeLeft] = useState(120);
  const [isTimerEnded, setIsTimerEnded] = useState(false);
  const [resendLoading, setResendLoading] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  const inputs = useRef([]);
  const timerRef = useRef(null);

  const formatTime = useCallback((time) => {
    const minutes = Math.floor(time / 60);
    const seconds = time % 60;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  }, []);

  const startTimer = useCallback(() => {
    if (timerRef.current) clearInterval(timerRef.current);

    setTimeLeft(120);
    setIsTimerEnded(false);

    timerRef.current = setInterval(() => {
      setTimeLeft((prevTime) => {
        if (prevTime <= 1) {
          clearInterval(timerRef.current);
          setIsTimerEnded(true);
          return 0;
        }
        return prevTime - 1;
      });
    }, 1000);
  }, []);

  useEffect(() => {
    if (modalVisibility.showModal3) {
      startTimer();
      setTimeout(() => {
        if (inputs.current && inputs.current[0]) {
          inputs.current[0].focus();
        }
      }, 300);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [modalVisibility.showModal3, startTimer]);

  const otpHandleChange = useCallback((index, value) => {
    const numericValue = value.replace(/[^0-9]/g, "");
    if (numericValue.length > 1) return;

    const newOtp = [...otp];
    newOtp[index] = numericValue;
    setOtp(newOtp);

    if (numericValue && index < 5 && inputs.current[index + 1]) {
      inputs.current[index + 1].focus();
    }
  }, [otp]);

  const handleKeyDown = useCallback((index, e) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0 && inputs.current[index - 1]) {
      inputs.current[index - 1].focus();
    }
  }, [otp]);

  const handleOtpPaste = useCallback((index, event) => {
    event.preventDefault();

    const pastedOtp = event.clipboardData
      .getData('text')
      .replace(/\D/g, '')
      .slice(0, 6);

    if (!pastedOtp) return;

    const nextOtp = new Array(6).fill('');
    const startIndex = pastedOtp.length === 6 ? 0 : index;

    pastedOtp.split('').forEach((digit, digitIndex) => {
      const targetIndex = startIndex + digitIndex;
      if (targetIndex < nextOtp.length) {
        nextOtp[targetIndex] = digit;
      }
    });

    setOtp(nextOtp);

    const focusIndex = Math.min(startIndex + pastedOtp.length - 1, 5);
    inputs.current[focusIndex]?.focus();
  }, []);

  const handleResendOTP = useCallback(async () => {
    setResendLoading(true);
    setError('');
    setMessage('');

    try {
      const response = await generateOtpForResendTpin({ user_id: storedUserid });
      if (response.status === 200) {
        setMessage('OTP has been resent successfully.');
        startTimer();
        setOtp(new Array(6).fill(''));
        setTimeout(() => {
          if (inputs.current && inputs.current[0]) {
            inputs.current[0].focus();
          }
        }, 300);
      } else {
        setError('Failed to resend OTP.');
      }
    } catch (error) {
      setError('Failed to resend OTP.');
    } finally {
      setResendLoading(false);
    }
  }, [storedUserid, startTimer]);

  const handleSubmitOTP = useCallback(async () => {
    setLoading(true);
    setMessage('');
    setError('');

    try {
      const response = await verifyOtpForTpin({ user_id: storedUserid, otp: otp.join('') });
      if (response?.data?.statusCode == "200") {
        setMessage('OTP verified successfully.');
        toast.success('OTP verified successfully.');
        getUserTpinStatus("OV");
        handleSubmitmodal3();
      } else {
        setError(response?.data?.message || 'Failed to verify OTP.');
        toast.error(response?.data?.message || 'Failed to verify OTP.');
      }
    } catch (error) {
      setError('Failed to verify OTP.');
      toast.error('Failed to verify OTP.');
    } finally {
      setLoading(false);
    }
  }, [storedUserid, otp, handleSubmitmodal3, getUserTpinStatus]);

  const localKeyDown = (index, e) => {
    if (e.key === "Enter" && otp.every((val) => val !== "")) {
      handleSubmitOTP();
    } else {
      handleKeyDown(index, e);
    }
  };

  const handleClose = () => {
    handleCloseModal3();
    setOtp(new Array(length).fill(''));
    setMessage('');
    setError('');
  };

  if (!modalVisibility.showModal3) return null;

  return (
    <Modal
      show={modalVisibility.showModal3}
      onHide={handleClose}
      centered
      backdrop="static"
      keyboard={false}
      className="email-optp-modle"
      style={{ zIndex: 1050 }}
    >
      <Modal.Body
        style={{
          backgroundColor: `var(--bs-primary1)`,
          color: `var(--bs-primary2)`,
          border: "2px solid var(--bs-primary3)",
          transform: "translateZ(0)",
        }}
      >
        <button
          onClick={handleClose}
          className="otp-close-btn"
          style={{
            position: "absolute",
            top: "10px",
            right: "10px",
            background: "transparent",
            border: "none",
            fontSize: "22px",
            color: "#fff",
            cursor: "pointer",
            zIndex: 2000,
          }}
        >
          ✕
        </button>
        <div className="set-head">
          <div className="row">
            <div className="col-lg-12">
              <div className="headinf-otp">
                <h2>OTP Verification</h2>
                <p className="set-lage">
                  We've sent a 6-digit verification code to your mobile number, please enter it here!!
                </p>
              </div>
              <div className="verification-code">
                <p>Verify OTP</p>
                <div className="resend-otp">
                  <span
                    className="resend-otp"
                    onClick={handleResendOTP}
                    style={{
                      cursor: timeLeft > 0 ? "default" : "pointer",
                      color: timeLeft > 0 ? "gray" : "gray",
                      pointerEvents: timeLeft > 0 ? "none" : "auto",
                    }}
                  >
                    {timeLeft > 0
                      ? `Resend in ${formatTime(timeLeft)}`
                      : "Resend OTP"}
                  </span>
                </div>
              </div>
              {/* OTP input section */}
              <div className="col-lg-12">
                <div className="otp-inputs">
                  {otp.map((value, index) => (
                    <input
                      key={index}
                      type="text"
                      inputMode="numeric"
                      pattern="[0-9]*"
                      maxLength="1"
                      value={value}
                      className="otp-input otp-input-login"
                      onChange={(e) => otpHandleChange(index, e.target.value)}
                      onKeyDown={(e) => localKeyDown(index, e)}
                      onPaste={(e) => handleOtpPaste(index, e)}
                      ref={(input) => (inputs.current[index] = input)}
                      onKeyPress={(e) => {
                        if (!/[0-9]/.test(e.key)) {
                          e.preventDefault();
                        }
                      }}
                    />
                  ))}
                </div>
              </div>
              <div className="col-lg-12">
                <div className="input-group">
                  <button
                    type="button"
                    disabled={otp.some((digit) => digit === '') || loading}
                    className={`mt-2 ${
                      otp.some((digit) => digit === '') || loading
                        ? "disableebuttoncls not-allowed"
                        : "btn-login"
                    }`}
                    onClick={handleSubmitOTP}
                  >
                    {loading ? "Submitting..." : "Submit OTP"}
                  </button>
                </div>
              </div>
              {message && (
                <div className="alert alert-success mt-3">{message}</div>
              )}
              {error && (
                <div className="alert alert-danger mt-3">{error}</div>
              )}
            </div>
          </div>
        </div>
      </Modal.Body>
    </Modal>
  );
};

export default React.memo(DashboardOtpModal);
